code_example:
template<typename T>
void f(T param); // param passed by value

const char* const ptr = "Fun with pointers";
// ptr is a const pointer to a const char object.

f(ptr); // T is deduced as const char*.
        // param's type is also const char*.
        // The top-level const on ptr is ignored.
        // The const on the pointee ('char') is preserved.
